29	const PROCESSING_FEE = 5;
30	
31	const BASE_PREMIUMS: Record<string, number> = {
32	  sword: 100,
33	  amulet: 60,
34	  staff: 80,
35	  potion: 40,
36	  rune: 25,
37	  moonstone: 25,
38	};
39	
40	const FIRST_INSURANCE_PERCENT = 10;
41	
42	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
43	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
44	// intermediates to stay exact, so every percentage goes through here.
45	const PERCENT_WHOLE = 100;
46	
47	const percentOf = (amount: number, percent: number): number =>
48	  (amount * percent) / PERCENT_WHOLE;
49	
50	// Rounding always favours MHPCO: premiums round up, payouts round down.
51	const roundPremium = (amount: number): number => Math.ceil(amount);
52	
53	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
54	
55	const BLOCK_SIZE = 3;
56	const BLOCK_BASE_PREMIUM = 60;
57	
58	const countByType = (items: Item[]): Map<string, number> => {
59	  const counts = new Map<string, number>();
60	  for (const item of items) {
61	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
62	  }
63	  return counts;
64	};
65	
66	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
67	
68	// A building block is exactly 3 alike components. Blocks are only offered on
69	// components, never on main items, and only at exactly 3 — 4 runes are priced
70	// per item, not as a block plus one.
71	const formsBuildingBlock = (type: string, count: number): boolean =>
72	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
73	
74	// A group of alike items is priced as a building block if it forms one, and
75	// per item otherwise.
76	const groupBasePremiumOf = (type: string, count: number): number =>
77	  formsBuildingBlock(type, count)
78	    ? BLOCK_BASE_PREMIUM
79	    : count * basePremiumOfType(type);
80	
81	// The policy base premium is the sum of the base premiums of each group of
82	// alike items.
83	const policyBasePremiumOf = (items: Item[]): number =>
84	  [...countByType(items)].reduce(
85	    (total, [type, count]) => total + groupBasePremiumOf(type, count),
86	    0,
87	  );
88	
89	const CURSE_PERCENT = 50;
90	
91	// Item-specific surcharges are additive percentages of the affected item's OWN
92	// base premium — they never compound with each other, and never apply to the
93	// policy total.
94	const HIGH_ENCHANTMENT_PERCENT = 30;
95	const HIGH_ENCHANTMENT_THRESHOLD = 5;
96	
97	const isHighlyEnchanted = (item: Item): boolean =>
98	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
99	
100	const surchargePercentOf = (item: Item): number =>
101	  (item.cursed ? CURSE_PERCENT : 0) +
102	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_PERCENT : 0);
103	
104	const itemSurchargesOf = (items: Item[]): number =>
105	  items.reduce(
106	    (total, item) =>
107	      total + percentOf(basePremiumOfType(item.type), surchargePercentOf(item)),
108	    0,
109	  );
110	
111	const quoteStep = (step: Step): QuoteResult => {
112	  const basePremium = policyBasePremiumOf(step.items);
113	  const itemSurcharges = itemSurchargesOf(step.items);
114	  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
115	
116	  return {
117	    premium: roundPremium(
118	      basePremium + itemSurcharges + firstInsuranceSurcharge + PROCESSING_FEE,
119	    ),
120	  };
121	};
122	
123	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
124	  results: scenario.steps.map(quoteStep),
125	});
